CREATE TABLE IF NOT EXISTS users (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,password_hash VARCHAR(200) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'STUDENT',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS exams (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,title VARCHAR(140) NOT NULL,category VARCHAR(80) NOT NULL,description VARCHAR(500),duration_minutes INT NOT NULL DEFAULT 15,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS questions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,exam_id BIGINT NOT NULL,question_text VARCHAR(1000) NOT NULL,option_a VARCHAR(400) NOT NULL,option_b VARCHAR(400) NOT NULL,option_c VARCHAR(400) NOT NULL,option_d VARCHAR(400) NOT NULL,correct_option CHAR(1) NOT NULL,explanation VARCHAR(800),CONSTRAINT fk_question_exam FOREIGN KEY(exam_id) REFERENCES exams(id));
CREATE TABLE IF NOT EXISTS attempts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,exam_id BIGINT NOT NULL,score INT NOT NULL,total INT NOT NULL,percentage DECIMAL(5,2) NOT NULL,submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_attempt_user FOREIGN KEY(user_id) REFERENCES users(id),CONSTRAINT fk_attempt_exam FOREIGN KEY(exam_id) REFERENCES exams(id));